/**
 * Registers the preview windows for the text's own definitions and theorems.
 *
 * The modules under src/definitions/ are generated by
 * scripts/gen-definitions.mjs: one copy of the body of every labelled
 * definition, theorem, lemma or corollary. They join the same tooltip
 * registry as the prerequisite concepts, but under the id `env:<label-id>`
 * (own namespace) and with variant "course": `:d[term]{#id}` gets a quiet grey
 * underline, and the window ends with a link to where the term is defined.
 */
import type { ComponentType } from "react";
import { registerConcept } from "../lib";
import { ConceptBody } from "./adapters";

type Meta = {
  id: string;
  kind: string;
  num: string;
  name: string | null;
  section: string;
  anchor: string;
};
type DefinitionModule = { default: ComponentType; meta: Meta };

const modules = import.meta.glob("../definitions/*.mdx", { eager: true }) as Record<
  string,
  DefinitionModule
>;

for (const mod of Object.values(modules)) {
  const { meta } = mod;
  const Body = mod.default;
  const label = `${meta.kind} ${meta.num}`;
  registerConcept({
    id: `env:${meta.id}`,
    title: meta.name ?? label,
    badge: meta.name ? label : undefined,
    variant: "course",
    body: (
      <ConceptBody>
        <Body />
      </ConceptBody>
    ),
    // one app is one page: the plain anchor is always the right target
    footer: (
      <a href={`#${meta.anchor}`}>
        → {label} in Section {meta.section}
      </a>
    ),
  });
}

export {};
